verus! {
    /// Clips each element of the input vector `a` to the inclusive range [min, max].
    /// Precondition: min < max.
    /// Postconditions:
    /// 1. The output vector has the same length as `a`.
    /// 2. For each index `i`, the output is
    ///    - `min` if `a[i] < min`
    ///    - `max` if `a[i] > max`
    ///    - `a[i]` otherwise.
    fn clip(a: Vec<i8>, min: i8, max: i8) -> Vec<i8>
        requires
            // The bounds define a non‐empty interval.
            min < max,
        ensures
            // Length is preserved.
            result.len() == a.len(),
        ensures
            // Each element is clipped into [min, max].
            forall |i: usize| (i < a.len()) ==>
                if a[i] < min {
                    result[i] == min
                } else if a[i] > max {
                    result[i] == max
                } else {
                    result[i] == a[i]
                }
    {
        let mut result: Vec<i8> = Vec::new();
        // Pre‐allocate to avoid re‐allocation in the loop
        result.reserve(a.len());

        let mut i: usize = 0;
        while i < a.len() {
            invariant
                // We never overshoot.
                i <= a.len();
            invariant
                // We have processed exactly `i` elements so far.
                result.len() == i;
            invariant
                // The first `i` elements satisfy the clipping property.
                forall |j: usize| j < i ==>
                    if a[j] < min {
                        result[j] == min
                    } else if a[j] > max {
                        result[j] == max
                    } else {
                        result[j] == a[j]
                    };
            decreases
                // We make progress toward termination.
                a.len() - i;

            let x = a[i];
            if x < min {
                result.push(min);
            } else if x > max {
                result.push(max);
            } else {
                result.push(x);
            }
            i += 1;
        }

        result
    }
}